cat > /tmp/model.mjs <<'EOF'
const A = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
export function enc(n){ // n BigInt >= 0
  if (n === 0n) return A[0];
  let s=""; while(n>0n){ const r=n%58n; n=n/58n; s=A[Number(r)]+s; } return s;
}
if (process.argv[2]) console.log(enc(BigInt(process.argv[2])));
EOF
node /tmp/model.mjs 58; node /tmp/model.mjs 0; node -e 'console.log((58n**1000n).toString())' > /tmp/big1000.txt; wc -c /tmp/big1000.txt; node -e 'console.log((2n**256n).toString())'

cd /tmp && node -e '
const vals=[];
for(let i=0;i<120;i++){
  const bits = 1 + Math.floor(Math.random()*200);
  let v=0n; for(let b=0;b<bits;b++){ v = v*2n + BigInt(Math.random()<0.5?0:1); }
  vals.push(v.toString());
}
console.log(vals.join("\n"));
' > /tmp/rand.txt; wc -l /tmp/rand.txt
fail=0; lead1=0; cnt=0
while read -r n; do
  exp=$(node /tmp/model.mjs "$n")
  o=$(/workspace/dataset/test20_executable --a 'T' --b '2' --c 'x' --d 'y' --e '3' --f "$n" --g "$n" 2>/dev/null)
  l5=$(echo "$o" | sed -n '5p'); l6=$(echo "$o" | sed -n '6p'); l9=$(echo "$o" | sed -n '9p')
  cnt=$((cnt+1))
  if [ "$l5" != "b'$exp'" ] || [ "$l9" != "b'$exp'" ] || [ "$l6" != "$n" ]; then fail=$((fail+1)); echo "MISMATCH n=$n l5=$l5 l6=$l6 l9=$l9 exp=b'$exp'"; fi
  case "$l5" in "b'1"*) if [ "$n" != "0" ]; then lead1=$((lead1+1)); echo "LEADING-1 for positive n=$n l5=$l5"; fi;; esac
done < /tmp/rand.txt
echo "checked=$cnt mismatches=$fail leading1_positive=$lead1"

cd /tmp && cat > /tmp/enc.mjs <<'EOF'
const A = "123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz";
const buf = Buffer.from(process.argv[2], 'utf8');
let nPad = 0; while(nPad < buf.length && buf[nPad]===0) nPad++;
let n = 0n; for (const b of buf) n = n*256n + BigInt(b);
let s = ""; if (n===0n) s=""; else { let m=n; while(m>0n){ s = A[Number(m%58n)] + s; m/=58n; } }
console.log(A[0].repeat(nPad) + (s===""? "" : s));
EOF
for s in 'Test123' 'hello world' 'A' 'zzzz' 'Ω≈ç' '~!@#$%^&*()' '0'; do
  exp=$(node /tmp/enc.mjs "$s")
  got=$(/workspace/dataset/test20_executable --a "$s" --b '2' --c 'x' --d 'y' --e '3' --f 1 --g 1 2>/dev/null | sed -n '1p')
  [ "$got" = "b'$exp'" ] && st=OK || st=MISMATCH
  echo "$st a=[$s] line1=$got expected=b'$exp'"
done
